package com.bte.controller;
import com.bte.repository.*;import com.bte.entity.*;import lombok.RequiredArgsConstructor;import org.springframework.web.bind.annotation.*;import org.springframework.transaction.annotation.Transactional;import org.springframework.security.core.Authentication;import java.util.*;import java.math.BigDecimal;
@RestController @RequiredArgsConstructor @Transactional(readOnly=true)
public class ParticipantHistoryController {
 private final UserRepository users;private final RegistrationRepository registrations;private final MatchResultRepository results;private final TournamentRoundRepository rounds;private final LedgerTransactionRepository ledger;
 public record MatchPerformance(int matchNumber,String mapName,String roomId,int teamRank,int placementPoints,int individualKills,int teamKills,int individualPoints,int teamPoints,String verificationStatus){}
 public record History(Long tournamentId,String title,String teamName,Integer slotNumber,int seat,String status,BigDecimal earnings,List<MatchPerformance> matches){}
 @GetMapping("/api/v1/me/tournament-history")public List<History> history(Authentication auth){
  var user=users.findByEmail(auth.getName()).orElseThrow();var entries=new LinkedHashMap<Long,Registration>();registrations.findByOwnerUserId(user.getId()).forEach(r->entries.put(r.getId(),r));registrations.findMemberEntries(user.getId()).forEach(r->entries.put(r.getId(),r));var output=new ArrayList<History>();
  for(var r:entries.values()){int position=1;for(int i=1;i<r.getSquadMembers().size();i++)if(user.getId().equals(r.getSquadMembers().get(i).getWalletUserId()))position=i+1;final int seat=position;var matches=new ArrayList<MatchPerformance>();
   for(var result:results.findByTournamentIdOrderByMatchNumberAsc(r.getTournament().getId())){var ranking=result.getRankings().stream().filter(row->Objects.equals(row.getPlayerUserId(),r.getOwnerUserId()) || Objects.equals(row.getPlayerUserId(),r.getGuestAccountId())).findFirst().orElse(null);if(ranking==null)continue;var member=r.getSquadMembers().get(seat-1);int kills=result.getPlayerScores().stream().filter(p->Objects.equals(p.getUserId(),user.getId()) || Objects.equals(p.getUserId(),member.getOriginalGuestUserId()) || (seat==1 && Objects.equals(p.getUserId(),r.getGuestAccountId()))).mapToInt(MatchPlayerScore::getKills).sum();if(result.getPlayerScores().isEmpty() && seat==1)kills=ranking.getKills();var round=rounds.findByTournamentIdAndRoundNumber(r.getTournament().getId(),result.getMatchNumber()).orElse(null);matches.add(new MatchPerformance(result.getMatchNumber(),round==null?"Match "+result.getMatchNumber():round.getMapName(),round==null?null:round.getRoomId(),ranking.getRank(),ranking.getPlacementPoints(),kills,ranking.getKills(),ranking.getPlacementPoints()+kills,ranking.getPlacementPoints()+ranking.getKills(),result.getVerificationStatus().name()));}
   var ids=new ArrayList<Long>();ids.add(user.getId());if(seat==1 && r.getGuestAccountId()!=null)ids.add(r.getGuestAccountId());if(!r.getSquadMembers().isEmpty()){var m=r.getSquadMembers().get(seat-1);if(m.getOriginalGuestUserId()!=null)ids.add(m.getOriginalGuestUserId());}BigDecimal earned=ledger.earnings(r.getTournament().getId(),ids);output.add(new History(r.getTournament().getId(),r.getTournament().getTitle(),r.getTeamName(),r.getSlotNumber(),seat,r.getTournament().getStatus().name(),earned==null?BigDecimal.ZERO:earned,matches));
  }return output;
 }
}
